import { ChevronDown, ChevronLeft, ChevronRight, X } from 'lucide-react'
import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react'

import { useMediaQuery } from '~/hooks/use-media-query'
import { useMounted } from '~/hooks/use-mounted'
import { lockBodyScroll, trapFocus } from '~/lib/overlay'
import { cx } from '~/lib/cx'
import styles from './sidebar.module.scss'

export type SidebarNavChild = {
  label: string
  href: string
  icon?: ReactNode
  permission?: string
}

export type SidebarNavItem = {
  label: string
  href?: string
  icon?: ReactNode
  permission?: string
  children?: SidebarNavChild[]
}

export type SidebarNavGroup = {
  group: string
  items: SidebarNavItem[]
  /** Allow the whole group to be collapsed from its heading. */
  collapsible?: boolean
  defaultOpen?: boolean
}

export interface SidebarProps {
  groups: SidebarNavGroup[]
  brand?: ReactNode
  /** Small square mark shown before the brand text. */
  brandMark?: ReactNode
  subtitle?: string
  mobileOpen?: boolean
  onMobileClose?: () => void
  footer?: ReactNode
  version?: string
  hasPermission?: (permission: string) => boolean
  defaultCollapsed?: boolean
  drawerSide?: 'left' | 'right'
  /** Render in-flow inside a frame (docs, settings previews). */
  contained?: boolean
  /** Current route. Pass `location.pathname` or your hash path. */
  currentPath?: string
}

function pathMatches(pathname: string, href: string) {
  return pathname === href || pathname.startsWith(`${href}/`)
}

function isHrefActive(pathname: string, href: string, siblingHrefs: string[]) {
  if (pathname === href) return true
  if (!pathname.startsWith(`${href}/`)) return false
  return !siblingHrefs.some(
    (other) =>
      other !== href &&
      other.length > href.length &&
      (pathname === other || pathname.startsWith(`${other}/`)),
  )
}

/** Responsive navigation with a collapsible desktop rail and nested groups. */
export function Sidebar({
  groups,
  brand = 'Vorzela UI',
  brandMark,
  subtitle,
  mobileOpen = false,
  onMobileClose = () => {},
  footer,
  version,
  hasPermission,
  defaultCollapsed = false,
  drawerSide = 'left',
  contained = false,
  currentPath,
}: SidebarProps) {
  const [collapsedDesktop, setCollapsedDesktop] = useState(defaultCollapsed)
  const [collapsedMobile, setCollapsedMobile] = useState(false)
  const [openItems, setOpenItems] = useState<Record<string, boolean>>({})
  const [closedGroups, setClosedGroups] = useState<Record<string, boolean>>({})
  const isDesktop = useMediaQuery('(min-width: 64rem)')
  const collapsed = isDesktop ? collapsedDesktop : collapsedMobile
  const isRight = drawerSide === 'right'
  const asideRef = useRef<HTMLElement>(null)
  const mounted = useMounted()

  // Resolve the route only after hydration. Reading `window.location` during
  // the first render would mark a different item active than the server did.
  const resolvedPath = useMemo(() => {
    if (currentPath !== undefined) return currentPath
    if (!mounted) return ''
    return `${window.location.pathname}${window.location.hash}`
  }, [currentPath, mounted])

  const closeMobile = useCallback(() => {
    setCollapsedMobile(false)
    onMobileClose()
  }, [onMobileClose])

  useEffect(() => {
    if (!mobileOpen) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') closeMobile()
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [mobileOpen, closeMobile])

  // Close the drawer when the viewport becomes desktop-sized.
  useEffect(() => {
    if (isDesktop && mobileOpen) closeMobile()
  }, [isDesktop, mobileOpen, closeMobile])

  // Keep the page behind the mobile drawer still and trap keyboard focus.
  useEffect(() => {
    if (!mobileOpen) return
    const node = asideRef.current
    const release = lockBodyScroll()
    const untrap = node ? trapFocus(node, closeMobile) : undefined
    return () => {
      release()
      untrap?.()
    }
  }, [mobileOpen, closeMobile])

  const can = useCallback(
    (permission: string) => hasPermission?.(permission) ?? true,
    [hasPermission],
  )

  const visibleGroups = useMemo(
    () =>
      groups
        .map((group) => ({
          ...group,
          items: group.items
            .filter((item) => !item.permission || can(item.permission))
            .map((item) => ({
              ...item,
              children: item.children?.filter(
                (child) => !child.permission || can(child.permission),
              ),
            }))
            .filter(
              (item) => !item.children || item.children.length > 0 || item.href,
            ),
        }))
        .filter((group) => group.items.length > 0),
    [groups, can],
  )

  const allHrefs = useMemo(() => {
    const hrefs: string[] = []
    for (const group of visibleGroups) {
      for (const item of group.items) {
        if (item.href) hrefs.push(item.href)
        for (const child of item.children ?? []) hrefs.push(child.href)
      }
    }
    return hrefs
  }, [visibleGroups])

  const toggleCollapsed = () => {
    if (isDesktop) {
      setCollapsedDesktop((value) => !value)
      return
    }
    setCollapsedMobile((value) => !value)
  }

  const handleParent = (item: SidebarNavItem) => {
    if (collapsed) {
      setCollapsedDesktop(false)
      setCollapsedMobile(false)
      setOpenItems((open) => ({ ...open, [item.label]: true }))
      return
    }
    setOpenItems((open) => ({
      ...open,
      [item.label]: !(open[item.label] ?? isItemOpenByRoute(item)),
    }))
  }

  const isItemOpenByRoute = (item: SidebarNavItem) =>
    Boolean(item.children?.some((child) => pathMatches(resolvedPath, child.href)))

  return (
    <>
      {mobileOpen ? (
        <button
          type="button"
          aria-label="Close navigation"
          className={styles.overlay}
          onClick={closeMobile}
        />
      ) : null}

      <aside
        ref={asideRef}
        className={cx(
          styles.root,
          collapsed && styles.collapsed,
          isRight && styles.right,
          mobileOpen && styles.open,
          contained && styles.contained,
        )}
        aria-label="Main navigation"
      >
        <div className={styles.header}>
          {collapsed ? null : (
            <>
              {brandMark ? (
                <span className={styles.brandMark}>{brandMark}</span>
              ) : null}
              <div className={styles.brand}>
                <span className={styles.brandName}>{brand}</span>
                {subtitle ? (
                  <p className={styles.brandSubtitle}>{subtitle}</p>
                ) : null}
              </div>
            </>
          )}

          <button
            type="button"
            className={styles.close}
            onClick={closeMobile}
            aria-label="Close menu"
          >
            <X aria-hidden />
          </button>
        </div>

        <nav className={styles.nav}>
          {visibleGroups.map((group) => {
            const hasActiveItem = group.items.some(
              (item) =>
                (item.href &&
                  isHrefActive(resolvedPath, item.href, allHrefs)) ||
                item.children?.some((child) =>
                  pathMatches(resolvedPath, child.href),
                ),
            )
            const groupOpen =
              closedGroups[group.group] ??
              (hasActiveItem ? true : (group.defaultOpen ?? true))

            return (
              <div key={group.group} className={styles.group}>
                {collapsed ? null : group.collapsible ? (
                  <button
                    type="button"
                    className={styles.groupHeadButton}
                    aria-expanded={groupOpen}
                    onClick={() =>
                      setClosedGroups((state) => ({
                        ...state,
                        [group.group]: !groupOpen,
                      }))
                    }
                  >
                    <span className={styles.groupLabel}>{group.group}</span>
                    <span className={styles.groupChevron} aria-hidden>
                      <ChevronDown />
                    </span>
                  </button>
                ) : (
                  <div className={styles.groupHead}>
                    <span className={styles.groupLabel}>{group.group}</span>
                  </div>
                )}

                {groupOpen
                  ? group.items.map((item) => {
                      const hasChildren = Boolean(item.children?.length)
                      const itemOpen =
                        openItems[item.label] ?? isItemOpenByRoute(item)
                      const active = item.href
                        ? isHrefActive(resolvedPath, item.href, allHrefs)
                        : Boolean(
                            item.children?.some((child) =>
                              pathMatches(resolvedPath, child.href),
                            ),
                          )

                      if (!hasChildren) {
                        return (
                          <a
                            key={item.label}
                            href={item.href}
                            className={cx(
                              styles.item,
                              active && styles.itemActive,
                            )}
                            aria-current={active ? 'page' : undefined}
                            aria-label={collapsed ? item.label : undefined}
                            data-label={collapsed ? item.label : undefined}
                            onClick={mobileOpen ? closeMobile : undefined}
                          >
                            {item.icon ? (
                              <span className={styles.itemIcon}>{item.icon}</span>
                            ) : collapsed ? (
                              <span className={cx(styles.itemIcon, styles.itemFallback)} aria-hidden>
                                {String(item.label).slice(0, 1)}
                              </span>
                            ) : null}
                            {collapsed ? null : (
                              <span className={styles.itemLabel}>{item.label}</span>
                            )}
                          </a>
                        )
                      }

                      return (
                        <div key={item.label}>
                          <button
                            type="button"
                            className={cx(
                              styles.item,
                              active && styles.itemActive,
                              itemOpen && styles.itemOpen,
                            )}
                            aria-expanded={collapsed ? undefined : itemOpen}
                            aria-label={collapsed ? item.label : undefined}
                            data-label={collapsed ? item.label : undefined}
                            onClick={() => handleParent(item)}
                          >
                            {item.icon ? (
                              <span className={styles.itemIcon}>{item.icon}</span>
                            ) : collapsed ? (
                              <span className={cx(styles.itemIcon, styles.itemFallback)} aria-hidden>
                                {String(item.label).slice(0, 1)}
                              </span>
                            ) : null}
                            {collapsed ? null : (
                              <>
                                <span className={styles.itemLabel}>{item.label}</span>
                                <span className={styles.chevron}>
                                  <ChevronDown aria-hidden />
                                </span>
                              </>
                            )}
                          </button>

                          {!collapsed ? (
                            <div
                              className={styles.childrenWrap}
                              data-open={itemOpen ? 'true' : 'false'}
                              inert={itemOpen ? undefined : true}
                            >
                              <div className={styles.childrenInner}>
                                <div className={styles.children}>
                                  {item.children?.map((child) => {
                                    const childActive = isHrefActive(
                                      resolvedPath,
                                      child.href,
                                      allHrefs,
                                    )
                                    return (
                                      <a
                                        key={child.href}
                                        href={child.href}
                                        className={cx(
                                          styles.item,
                                          styles.child,
                                          childActive && styles.itemActive,
                                        )}
                                        aria-current={childActive ? 'page' : undefined}
                                        onClick={mobileOpen ? closeMobile : undefined}
                                      >
                                        {child.icon ? (
                                          <span className={styles.itemIcon}>
                                            {child.icon}
                                          </span>
                                        ) : null}
                                        <span className={styles.itemLabel}>
                                          {child.label}
                                        </span>
                                      </a>
                                    )
                                  })}
                                </div>
                              </div>
                            </div>
                          ) : null}
                        </div>
                      )
                    })
                  : null}
              </div>
            )
          })}
        </nav>

        <div className={styles.footer}>
          {version ? <p className={styles.version}>v{version}</p> : null}
          {!collapsed && footer ? (
            <div className={styles.footerContent}>{footer}</div>
          ) : null}
          <button
            type="button"
            className={styles.collapse}
            onClick={toggleCollapsed}
            aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            data-label={collapsed ? 'Expand sidebar' : undefined}
          >
            {collapsed ? <ChevronRight aria-hidden /> : <ChevronLeft aria-hidden />}
            {collapsed ? null : <span>Collapse</span>}
          </button>
        </div>
      </aside>
    </>
  )
}

@use 'styles' as vz;

.overlay {
  position: fixed;
  inset: 0;
  z-index: calc(#{vz.z('modal')} - 1);
  border: 0;
  background: vz.color('foreground', 0.3);
  backdrop-filter: blur(2px);
  cursor: pointer;
  animation: vz-sidebar-fade 180ms vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.root {
  --sidebar-width: 16rem;

  position: fixed;
  inset: 0 auto 0 0;
  z-index: vz.z('modal');
  display: flex;
  width: var(--sidebar-width);
  height: 100svh;
  flex-direction: column;
  border-right: 1px solid vz.color('border');
  background: vz.color('card', 0.94);
  backdrop-filter: blur(20px) saturate(180%);
  color: vz.color('foreground');
  visibility: hidden;
  transform: translateX(-100%);
  transition:
    width vz.duration('slow') vz.ease('out'),
    transform vz.duration('slow') vz.ease('out'),
    visibility 0s linear vz.duration('slow');
  user-select: none;
  will-change: transform, width;
}

.right {
  right: 0;
  left: auto;
  border-right: 0;
  border-left: 1px solid vz.color('border');
  transform: translateX(100%);
}

.contained {
  position: relative;
  width: 100%;
  max-width: 18rem;
  height: 30rem;
  visibility: visible;
  transform: none;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  box-shadow: vz.elevation(1);
}

.contained .close {
  display: none;
}

.open {
  visibility: visible;
  transform: translateX(0);
  box-shadow: vz.elevation(3);
  transition:
    width vz.duration('slow') vz.ease('out'),
    transform vz.duration('slow') vz.ease('out'),
    visibility 0s;
}

.collapsed {
  --sidebar-width: 4.5rem;
}

.header {
  display: flex;
  height: 3.75rem;
  flex: none;
  align-items: center;
  gap: vz.space(3);
  padding-inline: vz.space(4);
  border-bottom: 1px solid vz.color('border');
}

.collapsed .header {
  justify-content: center;
  padding-inline: 0;
}

.brand {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 1px;
}

.brand-mark {
  display: inline-flex;
  width: vz.space(9);
  height: vz.space(9);
  flex: none;
  align-items: center;
  justify-content: center;
  border-radius: vz.radius('lg');
  background: vz.color('foreground');
  color: vz.color('background');
  font-size: vz.font-size('sm');
  font-weight: 700;
  letter-spacing: -0.02em;
  box-shadow: vz.elevation(1);
}

.brand-name {
  font-size: vz.font-size('sm');
  font-weight: 600;
  letter-spacing: -0.01em;

  @include vz.truncate;
}

.brand-subtitle {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: 0.625rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;

  @include vz.truncate;
}

.close {
  display: inline-flex;
  width: vz.space(8);
  height: vz.space(8);
  flex: none;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: vz.radius('sm');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;

  @include vz.hover {
    background: vz.color('accent');
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  svg {
    @include vz.icon(4);
  }
}

.nav {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: vz.space(4);
  padding: vz.space(3) vz.space(2);
  overflow: hidden auto;

  @include vz.scrollbar(8px);
}

.group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.group-head,
.group-head-button {
  display: flex;
  align-items: center;
  gap: vz.space(1);
  padding: 0 vz.space(2) vz.space(1);
}

.group-head-button {
  width: 100%;
  border: 0;
  border-radius: vz.radius('xs');
  background: transparent;
  color: inherit;
  cursor: pointer;
  text-align: left;

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.5);
}

.group-label {
  flex: 1;
  color: vz.color('muted-foreground');
  font-size: 0.625rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;

  @include vz.truncate;
}

.group-chevron {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  color: vz.color('muted-foreground');
  transition: transform vz.duration('fast') vz.ease('out');

  svg {
    @include vz.icon(3);
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.group-head-button[aria-expanded='false'] .group-chevron {
  transform: rotate(-90deg);
}

.item {
  position: relative;
  display: flex;
  width: 100%;
  min-height: vz.space(9);
  align-items: center;
  gap: vz.space(2.5);
  padding: vz.space(1.5) vz.space(2.5);
  border: 0;
  border-radius: vz.radius('sm');
  background: transparent;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('foreground', 0.05);
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);
}

.item-active {
  background: vz.color('foreground', 0.07);
  color: vz.color('foreground');
  font-weight: 600;
}

.item-icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;

  svg {
    @include vz.icon(4);
  }
}

.item-fallback {
  width: vz.space(4);
  height: vz.space(4);
  border-radius: vz.radius('xs');
  background: vz.color('accent');
  color: vz.color('accent-foreground');
  font-size: 0.625rem;
  font-weight: 700;
  text-transform: uppercase;
}

.item-label {
  flex: 1;
  min-width: 0;

  @include vz.truncate;
}

.chevron {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  transition: transform vz.duration('base') vz.ease('out');

  svg {
    @include vz.icon(3.5);
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.item-open .chevron {
  transform: rotate(180deg);
}

.children-wrap {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transition:
    grid-template-rows vz.duration('slow') vz.ease('out'),
    opacity vz.duration('base') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.children-wrap[data-open='true'] {
  grid-template-rows: 1fr;
  opacity: 1;
}

.children-inner {
  min-height: 0;
  overflow: hidden;
}

.children {
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin: vz.space(1) 0 vz.space(1) vz.space(5);
  padding-left: vz.space(3);
  border-left: 1px solid vz.color('border');
}

.child {
  min-height: vz.space(8);
  padding-block: vz.space(1);
  font-weight: 500;
}

.footer {
  display: flex;
  flex: none;
  flex-direction: column;
  gap: vz.space(1);
  padding: vz.space(2);
  border-top: 1px solid vz.color('border');
}

.version {
  margin: 0;
  padding-inline: vz.space(2);
  color: vz.color('muted-foreground');
  font-family: SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.625rem;
  text-align: center;
}

.footer-content {
  padding: 0 vz.space(2) vz.space(1);
  color: vz.color('muted-foreground');
  font-size: 0.625rem;
  line-height: 1.4;
  text-align: center;
}

.collapse {
  display: flex;
  width: 100%;
  min-height: vz.space(9);
  align-items: center;
  justify-content: center;
  gap: vz.space(2);
  border: 0;
  border-radius: vz.radius('sm');
  background: transparent;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  cursor: pointer;

  @include vz.hover {
    background: vz.color('accent');
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);

  svg {
    @include vz.icon(4);
  }
}

// Tooltip shown on the collapsed rail.
.collapsed .item[data-label]::after,
.collapsed .collapse[data-label]::after {
  content: attr(data-label);
  position: absolute;
  top: 50%;
  left: calc(100% + 0.5rem);
  z-index: vz.z('tooltip');
  padding: 0.25rem 0.5rem;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('sm');
  background: vz.color('popover');
  color: vz.color('popover-foreground');
  font-size: vz.font-size('xs');
  font-weight: 500;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-50%);
  transition: opacity vz.duration('fast') vz.ease('out');
}

.right .item[data-label]::after,
.right .collapse[data-label]::after {
  right: calc(100% + 0.5rem);
  left: auto;
}

@include vz.hover {
  .collapsed .item[data-label]:hover::after,
  .collapsed .collapse[data-label]:hover::after {
    opacity: 1;
  }
}

@include vz.motion-reduce {
  .root,
  .chevron,
  .group-chevron {
    transition: none;
  }
}

@include vz.up('lg') {
  .root {
    position: relative;
    visibility: visible;
    transform: none;
    box-shadow: none;
    transition: width vz.duration('slow') vz.ease('out');
    will-change: width;
  }

  .right {
    order: 2;
    transform: none;
  }

  .open {
    box-shadow: none;
  }

  .overlay,
  .close {
    display: none;
  }
}

@include vz.down('sm') {
  .root {
    --sidebar-width: min(18rem, 86vw);
  }
}

@keyframes vz-sidebar-fade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}
